package com.secureqr.scanner.ui.vault;
import android.content.res.ColorStateList;import android.view.*;import android.widget.*;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.secureqr.scanner.R;import com.secureqr.scanner.data.model.VaultItem;import com.secureqr.scanner.vault.VaultTypes;import java.util.*;
final class VaultTypeAdapter extends RecyclerView.Adapter<VaultTypeAdapter.H>{interface Click{void onClick(VaultTypes.Type t);}private final Click click;private VaultTypes.Category category;private List<VaultItem>items=Collections.emptyList();VaultTypeAdapter(Click c){click=c;}void submit(VaultTypes.Category c,List<VaultItem>i){category=c;items=i==null?Collections.emptyList():i;notifyDataSetChanged();}private int icon(VaultTypes.Type t){String k=t.key;if(VaultTypes.IDENTITY.equals(t.category))return"PASSPORT".equals(k)?R.drawable.ic_vault_passport:("DRIVER_LICENSE".equals(k)||"US_DRIVER_LICENSE".equals(k)?R.drawable.ic_vault_car:("SOCIAL_SECURITY".equals(k)?R.drawable.ic_vault_number:R.drawable.ic_vault_identity));switch(k){case"SOFTWARE_LICENSE":return R.drawable.ic_vault_license;case"SSH_KEY":return R.drawable.ic_key_line;case"API_KEY":return R.drawable.ic_vault_code;case"ACCESS_TOKEN":return R.drawable.ic_vault_tag;case"CERTIFICATE":return R.drawable.ic_vault_certificate;case"BANK_CARD":return R.drawable.ic_vault_card;case"CRYPTO_WALLET":return R.drawable.ic_vault_wallet;case"PAYMENT":return R.drawable.ic_vault_payment;case"EMAIL":return R.drawable.ic_vault_mail;case"CONTACT_INFO":case"OTHER_CONTACT":return R.drawable.ic_vault_contact;case"ID_PHOTO":return R.drawable.ic_vault_photo;case"CONTRACT":case"IMPORTANT_DOCUMENT":return R.drawable.ic_vault_contract;case"OTHER_ATTACHMENT":return R.drawable.ic_vault_attachment;default:return R.drawable.ic_vault_gear;}}private int color(VaultTypes.Type t){if(VaultTypes.IDENTITY.equals(t.category))return R.color.vault_icon_green;if(VaultTypes.FINANCIAL.equals(t.category))return R.color.vault_icon_orange;if(VaultTypes.CONTACT.equals(t.category))return R.color.vault_icon_purple;if(VaultTypes.FILES.equals(t.category))return R.color.vault_icon_cyan;if("ACCESS_TOKEN".equals(t.key))return R.color.vault_icon_purple;if("SSH_KEY".equals(t.key))return R.color.vault_icon_cyan;if("CERTIFICATE".equals(t.key))return R.color.vault_icon_green;return R.color.vault_icon_blue;}@NonNull public H onCreateViewHolder(@NonNull ViewGroup p,int v){return new H(LayoutInflater.from(p.getContext()).inflate(R.layout.item_vault_type,p,false));}public void onBindViewHolder(@NonNull H h,int p){VaultTypes.Type t=category.types.get(p);int n=0;for(VaultItem i:items)if(VaultTypes.matches(t,i.type,i.fieldsJson))n++;h.title.setText(t.labelRes);h.count.setText(String.valueOf(n));h.icon.setImageResource(icon(t));h.icon.setImageTintList(ColorStateList.valueOf(h.itemView.getContext().getColor(color(t))));h.itemView.setOnClickListener(v->click.onClick(t));}public int getItemCount(){return category==null?0:category.types.size();}static final class H extends RecyclerView.ViewHolder{TextView title,count;ImageView icon;H(View v){super(v);title=v.findViewById(R.id.tv_vault_type_title);count=v.findViewById(R.id.tv_vault_type_count);icon=v.findViewById(R.id.iv_vault_type_icon);}}}
